export const systems={bones:{name:'Skelett & Gelenke',latin:'Systema skeletale',color:'#e0d3b9',info:'Knochen stützen den Körper und schützen empfindliche Organe. Zusammen mit Gelenken und Muskeln ermöglichen sie Bewegung. Knochen speichern Mineralstoffe; Knochenmark ist an der Blutbildung beteiligt.',source:'bone'},muscles:{name:'Muskulatur',latin:'Systema musculare',color:'#bb7168',info:'Skelettmuskeln entwickeln durch Verkürzung Kraft. Über Sehnen bewegen sie Knochen, sichern Gelenke und halten die Körperhaltung. Ihre Arbeit erzeugt auch Wärme.',source:'muscle'},heart:{name:'Herz',latin:'Cor',color:'#984b4b',info:'Das Herz treibt Lungen- und Körperkreislauf an. Vorhöfe nehmen Blut auf, Herzkammern pumpen es weiter. Klappen begrenzen den Rückfluss.',source:'heart'},vessels:{name:'Blutgefäße',latin:'Vasa sanguinea',color:'#638aa1',info:'Arterien führen Blut vom Herzen weg, Venen führen es zurück. Der Austausch mit dem Gewebe erfolgt in den feinsten Gefäßen. Die Modellfarben kennzeichnen Gefäßtypen.',source:'vessel'},respiratory:{name:'Atmung',latin:'Systema respiratorium',color:'#d39e9a',info:'Atemwege leiten, reinigen, erwärmen und befeuchten die Luft. In der Lunge wird Sauerstoff ins Blut aufgenommen und Kohlendioxid abgegeben.',source:'air'},digestive:{name:'Verdauung',latin:'Systema digestorium',color:'#bb9783',info:'Der Verdauungstrakt zerlegt Nahrung und nimmt verwertbare Stoffe auf. Leber, Gallenblase und Bauchspeicheldrüse unterstützen diese Prozesse.',source:'gut'},nerves:{name:'Nervensystem',latin:'Systema nervosum',color:'#d3b26d',info:'Das Nervensystem verarbeitet Informationen und koordiniert Körperfunktionen. Gehirn und Rückenmark bilden das zentrale Nervensystem.',source:'brain'},urinary:{name:'Harnsystem',latin:'Systema urinarium',color:'#a67974',info:'Nieren bilden Urin. Harnleiter transportieren ihn zur Blase; die Harnröhre leitet ihn nach außen.',source:'kidney'},reproductive:{name:'Geschlechtsorgane',latin:'Systemata genitalia',color:'#c091a1',info:'Dargestellt sind männliche Geschlechtsorgane des Referenzmodells. Sie dienen der Bildung, Reifung und Weiterleitung von Spermien sowie der Fortpflanzung.',source:'reproduction'},endocrine:{name:'Hormonsystem',latin:'Glandulae endocrinae',color:'#bfa26d',info:'Endokrine Drüsen geben Hormone ins Blut ab. Hormone steuern unter anderem Stoffwechsel, Wachstum und die Reaktion auf Belastung.',source:'brain'},lymphatic:{name:'Lymphatische Organe',latin:'Systema lymphoideum',color:'#8d9b7f',info:'Lymphatische Organe sind an der Immunabwehr beteiligt. Der Thymus dient der Reifung bestimmter Abwehrzellen, die Milz filtert Blut.',source:'lymph'},senses:{name:'Sinnesorgane',latin:'Organa sensuum',color:'#81a6ab',info:'Sinnesorgane erfassen Reize. Augen ermöglichen Sehen; das Ohr ist an Hören und Gleichgewicht beteiligt.',source:'sensory'},skin:{name:'Haut & Haare',latin:'Integumentum commune',color:'#d5b19a',info:'Die Haut bildet die äußere Barriere des Körpers. Sie schützt, nimmt Reize auf und ist an der Temperaturregulation beteiligt.',source:'skin'}};
