// Longest match wins; descriptions apply to a structure family when a mesh depicts only a part.
export const entries=definitions.sort((a,b)=>b[0].length-a[0].length);
export function profile(m){return entries.find(a=>new RegExp('\\b'+a[0]+'\\b').test(m.en));}
export const health={
injury:{title:'Nach einer Verletzung',text:'Belastung zunächst unterbrechen und eine schmerzarme Position einnehmen. Bei leichter Schwellung kann vorsichtiges Kühlen durch ein Tuch lindern. Ein Modell zeigt nicht, ob etwas gezerrt, gerissen oder gebrochen ist.',warning:'Fehlstellung, offene Wunde, starke Schmerzen, neue Taubheit oder ein kalter/blasser Körperteil: dringend medizinisch abklären. Bei schwerer Verletzung 112. Nichts selbst einrenken.',source:'injury'},
ankle:{title:'Fuß und Sprunggelenk',text:'Bei einer leichten Verstauchung können Hochlagern, Kühlen durch ein Tuch und eine passende Bandage Beschwerden lindern. Wiederbelastung richtet sich nach Schwere und Schmerzen; bei unklarem Befund ärztlich abklären.',warning:'Nach Unfall nicht auftreten können, deutliche Fehlstellung, zunehmende Schmerzen oder plötzlich fehlende Abstoßkraft: zeitnah untersuchen lassen. Ein Sehnenriss kann auch ohne sichtbare Wunde vorliegen.',source:'ankle'},
wrist:{title:'Hand und Handgelenk',text:'Nach einem Sturz Belastung unterbrechen, schmerzarm stützen und Schwellung vorsichtig kühlen. Anhaltende Schmerzen sollten untersucht werden; ein Bruch ist äußerlich nicht immer erkennbar.',warning:'Fehlstellung, Gefühlsstörungen oder starke Schmerzen benötigen rasche ärztliche Hilfe. Ringe bei beginnender Schwellung vorsichtig abnehmen, sofern leicht möglich.',source:'wrist'},
back:{title:'Rückenbeschwerden',text:'Bei unspezifischen Rückenschmerzen ohne Warnzeichen hilft meist angepasste Alltagsbewegung; längere Bettruhe vermeiden. Wärme kann angenehm sein. Nach Unfall oder bei neuen starken Beschwerden zuerst die Ursache abklären.',warning:'Neue Lähmung, Taubheit im Genital-/Sitzbereich oder Verlust der Blasen- beziehungsweise Darmkontrolle: sofort in die Notaufnahme, bei schweren akuten Ausfällen 112.',source:'back'},
shoulder:{title:'Schulterbeschwerden',text:'Belastung anpassen und schmerzauslösende Bewegungen reduzieren. Bei vielen Schulterproblemen helfen gezielte Übungen beziehungsweise Physiotherapie nach Abklärung. Nach einem Unfall mit deutlichem Funktionsverlust rasch untersuchen lassen.',warning:'Keine Selbst-Einrenkung. Plötzlich fehlende Armkraft, Fehlstellung oder Taubheit sind Warnzeichen. Schulter-/Armschmerz zusammen mit Brustdruck, Atemnot oder kaltem Schweiß: 112.',source:'painShoulder'},
chest:{title:'Brustschmerzen ernst nehmen',text:'Schmerzen im Brustbereich lassen sich nicht durch Anklicken eines Muskels oder Organs zuordnen. Herz, Lunge, Speiseröhre und Bewegungsapparat können ähnliche Beschwerden verursachen.',warning:'Neuer starker oder anhaltender Brustdruck, Atemnot, kalter Schweiß, Übelkeit oder Ausstrahlung in Arm/Kiefer/Rücken: sofort 112. Nicht selbst fahren; Belastung stoppen.',source:'heartAttack'},
breathing:{title:'Beschwerden beim Atmen',text:'Atemnot hat verschiedene Ursachen und ist kein Befund, der allein anhand der Anatomie bewertet werden kann. Neue oder zunehmende Beschwerden medizinisch abklären.',warning:'Starke oder plötzlich einsetzende Atemnot, bläuliche Lippen, Brustschmerz oder Bewusstseinsstörung: 112. Eine atemerleichternde, meist aufrechte Position zulassen.',source:'emergency'},
neuro:{title:'Neurologische Beschwerden',text:'Die Lage einer Hirnstruktur erklärt nicht die Ursache von Kopfschmerzen, Schwindel oder Gefühlsstörungen. Neue oder wiederkehrende Beschwerden benötigen eine passende Untersuchung.',warning:'Plötzliche einseitige Schwäche, hängender Mundwinkel, Sprach-/Sehstörung oder ungewohnt stärkster Kopfschmerz: sofort 112, auch wenn es wieder besser wird. Zeitpunkt des Beginns merken.',source:'stroke'},
abdominal:{title:'Bauchbeschwerden',text:'Die Schmerzstelle allein erlaubt keine sichere Zuordnung zu einem Organ. Anhaltende, zunehmende oder wiederkehrende Beschwerden ärztlich abklären; Begleitsymptome und zeitlichen Verlauf notieren.',warning:'Plötzlich sehr starke Bauchschmerzen, harter Bauch, Kreislaufprobleme oder Bewusstseinsstörung: 112. Blut im Erbrochenen oder Stuhl und starke Schmerzen benötigen sofortige medizinische Abklärung.',source:'abdominalHealth'},
appendix:{title:'Verdacht auf Blinddarmentzündung',text:'Typisch sind zunehmende Bauchschmerzen, die sich in den rechten Unterbauch verlagern können, oft mit Übelkeit oder Fieber. Beschwerden können aber untypisch sein. Bei Verdacht umgehend untersuchen lassen.',warning:'Starke zunehmende Bauchschmerzen mit deutlicher Verschlechterung, hartem Bauch oder Kreislaufproblemen: 112. Nicht auf eine Selbstdiagnose durch Drücken oder Bewegungstests verlassen.',source:'appendix'},
urinary:{title:'Beschwerden der Harnwege',text:'Brennen beim Wasserlassen, Blut im Urin oder Flankenschmerzen sind Gründe für eine ärztliche Abklärung. Die Ursache kann der Atlas nicht bestimmen.',warning:'Flankenschmerz mit Fieber/Schüttelfrost, fehlendes Wasserlassen oder starke akute Schmerzen: dringend medizinisch abklären. Bei schwerem Allgemeinzustand oder Kreislaufproblemen 112.',source:'urinaryHealth'},
general:{title:'Beschwerden richtig einordnen',text:'Diese Struktur ist anatomisch dargestellt. Es gibt hier noch keine eigens geprüfte Anleitung für Beschwerden an diesem einzelnen Teil. Für eine Behandlung sind Symptome, Verlauf und Untersuchung entscheidend.',warning:'Bei Lebensgefahr 112. Bei dringenden, nicht lebensbedrohlichen Beschwerden außerhalb der Sprechzeiten hilft in Deutschland die 116117.',source:'first'}
};
export function healthFor(m){const p=profile(m);if(p)return health[p[6]];return health[({bones:'injury',muscles:'injury',heart:'chest',vessels:'general',respiratory:'breathing',digestive:'abdominal',nerves:'neuro',urinary:'urinary'})[m.system]||'general'];}
// Unterschiede zwischen weiblicher und männlicher Anatomie an Stellen, die das (männliche) Referenzmodell zeigt.
// Jede Aussage ist mit dem verlinkten OpenStax-Kapitel abgeglichen.
Object.assign(sources,{urineTransport:[base+'25-2-gross-anatomy-of-urine-transport','OpenStax · Harnleiter, Blase und Harnröhre'],female:[base+'27-2-anatomy-and-physiology-of-the-ovarian-reproductive-system','OpenStax · Weibliche Geschlechtsorgane'],sexDev:[base+'27-3-development-of-the-male-and-female-reproductive-systems','OpenStax · Entwicklung der Geschlechtsorgane']});
const sexNotes=[
 [/\bhip bone\b/,'Das Hüftbein ist der Knochen, an dem sich weibliches und männliches Skelett am sichersten unterscheiden lassen. Das weibliche Becken ist an die Geburt angepasst: breiter, mit größerem Schambogenwinkel (über 80° statt unter 70°), rundlich-ovalem Beckeneingang und weiterer, flacherer Beckenhöhle. Männliche Beckenknochen sind meist dicker und schwerer.','pelvis'],
 [/^sacrum$/,'Bei Frauen ist das Kreuzbein meist breiter, kürzer und weniger gekrümmt; sein oberer Vorsprung ragt weniger in das Becken. Dadurch ist der weibliche Beckeneingang runder.','pelvis'],
 [/^urethra$/,'Die Harnröhre ist das einzige Organ der Harnwege mit deutlichem Unterschied: bei Frauen etwa 4 cm, bei Männern im Mittel etwa 20 cm lang. Die kurze weibliche Harnröhre gilt als wichtigster Grund, warum Harnwegsinfekte bei Frauen häufiger sind. Beim Mann verläuft sie durch Prostata und Penis.','urineTransport'],
 [/^urinary bladder$|\bureter\b|\bkidney\b/,'Nieren, Harnleiter und Harnblase sind bei Frauen und Männern gleich aufgebaut. Nur die Harnröhre unterscheidet sich deutlich.','urineTransport'],
 [/^prostate$/,'Die Prostata gibt es nur beim Mann. Sie liegt direkt unter der Harnblase und umschließt den Anfang der Harnröhre.','urineTransport'],
 [/\btestis\b/,'Hoden und Eierstöcke sind die Keimdrüsen (Gonaden) und entstehen aus derselben Anlage im Embryo. Die Eierstöcke liegen in der Beckenhöhle und bilden Eizellen. Sie sind im Modell nicht enthalten.','female'],
 [/epididymis|deferent duct|seminal vesicle/,'Diese Strukturen entstehen im Embryo aus dem Wolff-Gang. Ohne Testosteron bildet er sich zurück, und aus dem Müller-Gang entwickelt sich stattdessen das innere weibliche Genitale mit Eileitern und Gebärmutter.','sexDev'],
 [/glans penis|corpus cavernosum|corpus spongiosum/,'Eichel des Penis und Klitoris entstehen aus denselben embryonalen Zellen: unter Testosteron die Eichel des Penis, ohne Testosteron die Klitoris.','sexDev'],
 [/thyroid cartilage/,'Der Schildknorpel bildet den „Adamsapfel“, der bei Männern meist stärker hervortritt. In der Pubertät lässt Testosteron den Kehlkopf wachsen und die Stimmlippen länger und dicker werden – die Stimme wird tiefer.','sexDev'],
 [/pubococcygeus|puborectalis|iliococcygeus|\bcoccygeus\b|levator ani/,'Der Beckenboden trägt die Beckenorgane. Bei beiden Geschlechtern ziehen Analkanal und Harnröhre hindurch, bei Frauen zusätzlich die Scheide.','trunk'],
 [/pectoralis major/,'Bei Frauen liegt vor der Brustmuskulatur die Brustdrüse. Brustdrüsen sind umgewandelte Schweißdrüsen; die Milch gelangt über 15 bis 20 Milchgänge zur Brustwarze. Im Modell ist keine Brustdrüse enthalten.','female']
];
export function sexNote(m){const n=sexNotes.find(([re])=>re.test(m.en));return n?{text:n[1],source:n[2]}:null}
